/**
 * Return one page of the invitations sent to the caller's email address that they have not answered, the newest first, each with the organization and who invited them. One that ran out of time is listed as expired until it is canceled or replaced. A missing cursor starts at the first page and nextCursor null ends the list.
 * @summary List the caller's invitations
 */
export const listInvitationsQueryLimitDefault = 50;
export const listInvitationsQueryLimitMax = 100;

export const listInvitationsQueryCursorMax = 4096;

export const listInvitationsQueryCursorRegExp = new RegExp("^[A-Za-z0-9_-]+$");

export const ListInvitationsQueryParams = zod.object({
  limit: zod
    .int()
    .min(1)
    .max(listInvitationsQueryLimitMax)
    .default(listInvitationsQueryLimitDefault)
    .describe("Most items in one page."),
  cursor: zod
    .string()
    .min(1)
    .max(listInvitationsQueryCursorMax)
    .regex(listInvitationsQueryCursorRegExp)
    .optional()
    .describe(
      "Opaque continuation from the previous page's nextCursor, bound to the organization and the filters that made it. The server only ever issues cursors written in URL-safe base64 (letters, digits, - and _, no padding) and refuses anything else, so the pattern says so. A cursor that fits the pattern can still be refused: one this list never gave out, or one made for another organization or other filters.",
    ),
});

export const listInvitationsResponseNextCursorMax = 4096;

export const listInvitationsResponseNextCursorRegExp = new RegExp(
  "^[A-Za-z0-9_-]+$",
);

export const ListInvitationsResponse = zod.object({
  invitations: zod
    .array(
      zod
        .object({
          id: zod.string().describe("The invitation's id. Opaque."),
          organization: zod
            .object({
              id: zod.string().describe("The organization's id. Opaque."),
              slug: zod.string().describe("Its short name."),
              name: zod.string().describe("What people call it."),
            })
            .describe("The organization it is an invitation to."),
          role: zod
            .enum(["admin", "member"])
            .describe("A role an admin can give a person."),
          status: zod
            .string()
            .describe(
              "pending while it can still be answered. expired once its seven days ran out, accepted or declined once the person answered, canceled when the organization took it back.",
            ),
          invitedBy: zod
            .object({
              name: zod
                .string()
                .nullable()
                .describe("What OpenBot calls them. Null until they choose."),
              email: zod.string().describe("Their address."),
            })
            .describe("Who sent an invitation."),
          createdAt: zod.iso
            .datetime({ offset: true })
            .describe("When it was sent."),
          expiresAt: zod.iso
            .datetime({ offset: true })
            .describe("When it stops being accepted."),
        })
        .describe(
          "An invitation as the person it was sent to sees it. status is the server's verdict.",
        ),
    )
    .describe("The newest first."),
  nextCursor: zod
    .string()
    .max(listInvitationsResponseNextCursorMax)
    .regex(listInvitationsResponseNextCursorRegExp)
    .nullable()
    .describe(
      "Pass as cursor for the next page. Null ends the list. Written in URL-safe base64, the only form the cursor parameter accepts.",
    ),
});

